<?php
require_once __DIR__.'/../../config/config.php';$user=require_roles(['ADMIN','HR']);$pdo=db();$status=trim((string)($_GET['status']??'PENDING'));$qText=trim((string)($_GET['q']??''));$where=[];$params=[];if(in_array($status,['PENDING','APPROVED','REJECTED','CANCELLED'],true)){$where[]='r.status=?';$params[]=$status;}if($qText!==''){$where[]='(e.employee_number LIKE ? OR e.first_name LIKE ? OR e.last_name LIKE ? OR r.requested_field LIKE ?)';array_push($params,"%$qText%","%$qText%","%$qText%","%$qText%");}$condition=$where?' WHERE '.implode(' AND ',$where):'';$stmt=$pdo->prepare('SELECT r.*,e.employee_number,e.first_name,e.last_name FROM profile_change_requests r JOIN employees e ON e.id=r.employee_id'.$condition.' ORDER BY r.created_at DESC');$stmt->execute($params);$requests=$stmt->fetchAll();$pageTitle='Change requests';require __DIR__.'/../../includes/header.php';?><div class="mb-7"><p class="text-sm text-slate-500">Employee self-service approvals</p><h1 class="font-display text-3xl font-bold mt-1">Change requests</h1></div><form class="bg-white border rounded-xl p-4 mb-5 flex gap-3"><input name="q" value="<?=e($qText)?>" placeholder="Search employee or field" class="field !mt-0"><select name="status" class="field !mt-0"><option value="">All statuses</option><?php foreach(['PENDING','APPROVED','REJECTED','CANCELLED'] as $option):?><option <?= $status===$option?'selected':''?>><?=e($option)?></option><?php endforeach;?></select><button class="rounded-lg bg-slate-900 px-5 py-2 text-sm font-bold text-white">Filter</button></form><section class="bg-white border rounded-xl p-6 overflow-x-auto"><table class="w-full text-left text-sm"><thead class="text-xs uppercase text-slate-400"><tr><th class="py-3">Employee</th><th>Type</th><th>Field</th><th>Submitted</th><th>Status</th><th></th></tr></thead><tbody class="divide-y"><?php foreach($requests as $request):?><tr><td class="py-3"><b><?=e($request['first_name'].' '.$request['last_name'])?></b><small class="block text-slate-400"><?=e($request['employee_number'])?></small></td><td><?=e($request['request_type'])?></td><td><?=e($request['requested_field'])?></td><td><?=e($request['created_at'])?></td><td><?=e($request['status'])?></td><td><a class="font-bold text-teal-700" href="view.php?id=<?=$request['id']?>">Review</a></td></tr><?php endforeach;?></tbody></table><?php if(!$requests):?><p class="py-8 text-center text-slate-500">No requests found.</p><?php endif;?></section><?php require __DIR__.'/../../includes/footer.php';